INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p271700-me399', 'stk-majed-kfupm', 'ME 399', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته\n\nقدمت على ارامكو للتدريب الصيفي وقبلت في منطقة تسمى شدقم\n\nوتبعد عن الحساء 20 الى 30 كيلو\n\nلكني اريد التدريب في الرياض وما حولها\n\nفأي واحد من الاخوان طالب في الهندسة الميكانيكية\n\nوعنده تدريب في الصيف في ارامكو في الرياض او الوسيع ويريد التبديل معي\n\nارسال رسالة لي\n\nوشكرا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/63527/1", "user": "MAJED-KFUPM", "ts": 1212676843000, "tid": 63527, "pn": 1}}', 1212676843000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p272398-me399', 'stk-user474', 'ME 399', 'info', '{"desc": "مكان التدريب له علاقة وثيقة بمكان الإقامة\nو فرص التبديل موجودة لكن محصورة لسبب بسيط\nلو فتحوا المجال لصارت فوضى\n\nو لكن نصيحتي للي بشدقم, تراها منطقة حية و ماراح تندم أبدا خصوصا إذا كنت مهندس ميكانيكي أو كهربائي ;), لديهم منطقة حيوية هناك, و رأس مالها شهرين, أنا واحد تدرب بالظهران في راحة و لكن الإستفادة لا تقارن بشدقم, يا ليتني كنت هناك كوني مهندس كهربائي. تتعرف على جو العمل الحقيقي لا المكتبي ,وتستفيد كثيرا خصوصا في ال 4rth level courses إذا كنت إنسان طموح.\n\nو أعتقد في سكن ببلاش و ميزات أخرى من أكل و غيره :), أسأل اللي راحوا قبلك يمكن يفيدونك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/63527/14", "user": "user474", "ts": 1212924680000, "tid": 63527, "pn": 14}}', 1212924680000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1499346-me399', 'stk-m_nd_m', 'ME 399', 'info', '{"desc": "بسم الله الرحمن الرحيم\n\nالسلام عليكم و رحمة الله و بركاته\n\nقمت بإنشاء استبيان يلخص تجارب الطلاب في برنامج أرامكو الصيفي، يحتوي على معلومات و نصائح و غيرها.\n\nالنتائج ستقسم لقسم أسئلة عامة و قسم التجارب:\n\n**\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\(1\\)\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-**![upload_2018-9-12_1-7-3.png|644x316](upload://5KO3SUeZcF4ldwNQjNE0WTv08Ye.png)**\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\(2\\)\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-**![upload_2018-9-12_1-9-14.png|909x413](upload://yZ9wfdQS7Y4QfDEwI3qXcJhY1hQ.png)**\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\(3\\)\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-**![upload_2018-9-12_1-9-37.png|875x457](upload://iS8gC07uQWP2CjtkVdLpnqkChh9.png)**\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\(4\\)\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-**![upload_2018-9-12_1-9-57.png|889x380](upload://hvB1XYW1vc3btiiMptpbmvU2TCv.png)**\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\(5\\)\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-**![upload_2018-9-12_1-10-12.png|877x395](upload://eWd2KvuEn9lXxR5UTjFPDGnCKgw.png)~~~~~~~~~~~~~~~~~~~~~~~~تجارب~~~~~~~~~~~~~~~~~~~~~~~~عدد \\(10\\) مشاركات: 8 ميكانيكال \\- 1 بتروليوم \\- 1 كهرب5 أسئلة كالتالي/\\(e.g. Project Management Team or PMT\\) القسم \\- Department\\(e.g. Forecasting & Logisitics Division or F&LD\\) الشعبة \\- Division\\(e.g. Gas Forecasting Unit\\) الوحدة \\- Unitطبيعة عمل القسم \\- Departments Work | \\(مثال: التأكد من توفر المواد لاستمرار المشاريع و عدم توقفها\\)إضافات \\- Additions | \\(التحدث عن بيئة العمل، أي نصائح، جدية التدريب، المواصلات، السكن، إيجابيات، سلبيات، الدوام، الحضور الخ الخ\\)\\*\\*\\*ملاحظة: لم يتم التعديل على أي من الردود\\*\\*\\***\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\(1\\)\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-****FrPD****SIS****Support service unit****Protect assets & save lives****You’ve got to be able to work in a team \\+ to communicate with others \\+ leave a good impression** **\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\(2\\)\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-****Northern Area Pipelines Department****Maintenance Division****Maintenance planning, engineering unit****Transport oil and gas from refineries to factories by operating and maintaining the pipeline network and its facilities in a safe and environmentally friendly manner using modern technologies.****انا كنت تبع ال maintenance ولكن ال mentor قال لي بما إن التدريب مدته ٨ اسابيع وهي تعتبر مدة قليلة وانا ابيك تاخذ فايدة كبيرة****راح اقسم الخطة الى التالي :****2 weeks in Operation Division****2 weeks in Maintenance Division****2 weeks in Hot tap & Stopple Division****2 weeks in Engineering Division****بكل صراحة تجربة التدريب عندهم مو مرتبة ابداً****م عندهم برنامج معين ومحدد لتدريب الطالب واول اسبوع يوم رحنا م كانوا يدرون اصلاً ان في طلاب تدريب صيفي عندهم.****بالنسبة للمواصلات كنت اروح واجي بسيارتي.****م اعطونا سكن .****ايجابيات :****اللي قابلتهم هناك يحرجونك بأخلاقهم العالية ويبون يعلمونك قد م يقدرون لكن بيئة العمل احياناً تمنعهم من هالشي. لان مو كل وقت الموظفين فاضين عندهم اجتماعات و الخ ...** **فكرة تقسيم التدريب الى اسبوعين في كل division كنت فكرة ممتازة واخذت فائدة كبيرة منها.****سلبيات :****م فيه برنامج معين للتدريب وتحس كل شي ملخبط وتجي لك ايام احياناً م تسوي شي اساساً ف يكون مضيعة للوقت مع الاسف.****الدوام من ٧ الى ٤.****لكن كان فيه flexibility بحيث لو خلصت شغلي وماعندي شي اسويه اقدر امشي.****\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\(3\\)\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-****EXPEC ARC****PTT****Advance well complition** **البحث عن حلول جديدة لتحديات يواجهونها في حقول البترول****المكافأة بالضبط كانت 3083.33 الشهر الأول****الشهر الثاني باقي ما وصلت****ايجابيات:****١\\- في تعاون كبير جدا ومرونه مع ظروف الطالب****حصلت معاي حالت وفاة وعطوني الاربعاء والخميس اجازة اذا عندي موعد او اي شيء طارئ يسمحون لي بالخروج وبسهوله** **٢\\- بعض الموظفين متعاون وتحس انه يبغا يفيدك وقد ما تسئلة يجاوب بدون ما يحسسك انه مل منك او تضايق وبعضهم يصرفك وما له خلق** **السلبيات:** **١\\- انا ميكانيكال انجنيير و ٩٠٪؜ من الشغل كان كيمياء مع ان الشغله الي كنت اسويها عاجبتني لكن ما كانت تضيفلي اي شيء كمهندس ميكانيكي والديبارتمت الي كنت فيه بشكل عام ما عندهم شغل حق المهندس الميكانيكي****٢\\- توزيع الطلاب بناء على التخصص ما كان ممتاز ابدا لأن كان ممكن يحطوني في ديبارتمنت ثاني له علاقة اكبر بتخصصي وكان استفدت اكثر****بشكل عام كانت تجربه رائعة واستفدت منها كثير من ناحية اجواء الوظيفة والمهام الوظيفية الي تجي الموظفين والنشاطات الي تسويها الشركة والاجتماعات وكيفية التعامل معاها****لكن زي ما ذكرت فوق للأسف ما حصلت الفايدة الي كنت احتاجها كمهندس ميكانيكي****\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\(4\\)\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-****PMT****Marjan Downstream Pipelines****\\*No Unit Mentioned\\*****Design Office** **I Got engaged with the designers\\(the contractor\\) to know more about pipelines and their designs and also understand how to read the P&ID which is Piping and Instrumentation Diagram. Finally I was assigned in the E\\-Review System which is a system where the reviewers put their comments in the designs so the designers see where the mistakes are and they correct them, my assignment was to approve that the designers had corrected their designs based on the implemented documents and upload them on the system.** **\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\(5\\)\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-****Inspection Department****ما اذكر بالضبط****Advanced Non Distractive Test Services Unit****عمل الفحوصات على المعدات الميكانيكية والبيبات** **كان العمل جماعي ، وما لاقيت صعوبة ، قرب العمل من الجامعة جعله مريح ...****تجربة قصيرة الوقت ، لكن تغيير جو****\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\(6\\)\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-****Process and control systems department****Energy systems division****Energy systems optimization unit****Energy audit for non\\-industrial building** **بيئة العمل جدا ممتازة \\( تعاون ، اخلاق ، النصائح \\)** **\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\(7\\)\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-****Maintenance****Reliability****\\*No Unit Mentioned\\*****صيانة الكومبرسرات والبمبات****للامانة لم يركزو علي للقيام باي عمل بتاتا، اغلب الايام جالس عالمكتب وكم يوم كان ياخذني واحد من التكنشنز للمصنع عشان اتفرج ولا شيء اخر، تندمت على التطبيق معهم****\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\(8\\)\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-****ITC****Job skills****Electrical core****لايوجد****.****\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\(9\\)\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-****EXPEC Arc****Production technology**\\*No Unit Mentioned\\*اجراء الأبحاث والعمل على تطوير تقنيات الانتاج وحل مشاكل المتعلقة بالانتاجبيئة العمل كانت جيدة ومريحة.من ناحية جدية التدريب فهو يعتمد على المشرف على الطالب وعلى الطالب أيضا. فالطالب يقدر يطرح أسئلة و يتكلم مع الموظفين حتى لو موب في نفس الفريق او القسم. فالشيء هذا يبين ان الطالب مهتم وممكن ياخذ شغل اكثر وينظرون للطالب بجدية. انا من سكان مدينة الخبر فما كان عندي مشكلة في المواصلات او السكن. من السلبيات ان مرات يكون غير سوء تنظيم بين الجامعة والشركة. قابلت بعض الطلاب خططهم ما كانت جاهزة و عدد كبير تأخر حصولهم على اجهزة كمبيوتر.**\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\(10\\)\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-\\-****\\(تجرتبي الشخصية، اللي عنده أي سؤال يتفضل\\)****PMT**Forecasting & Logisitics DivisionGas Forecasting Unitباختصار التأكد من توفر المواد \\(مثل البايبس و الفالفز\\) لاستمرار مشاريع الغاز و عدم توقفها.الإضافات على شكل نقاط: - تعامل الموظفين كان جميل جدًا و متعاونين لأقصى درجة. - قعدت أسبوع و شوي بس عشان أستلم جهاز و أفعل حسابي و الـPulse، برأيي سوء تنظيم و تخطيط. - مافيه شغل إلا إذا نشبت باستمرار \\(وهذا اللي حاولت أسويه\\) أو إذا تعرف أحد يقربلك ممكن يساعدك، أما إذا قعدت بالمكتب تنتظر يجي الشغل عندك بتموت زهق. - ما كان فيه متابعة على الحضور و الغياب، لكن من نفسي حاولت ألتزم قدر المستطاع و ماسمعت كلمة وينك متأخر ولا شي من هذا القبيل، بالعكس متعاونين جدًا حتى إني مرضت بأول أسبوع و أصر موظف الإتش أر إني أغيب و أرتاح. - تعلمت كثير أشياء لكن نصيحتي هي النشبة النشبة. - بخصوص المواصلات و السكن مالي علم، بخصوص تذاكر السفر فبإمكانك تسافر مجانًا لكن بتقعد على أعصابك لأنه ما يأكدونلك الحجز إلا بآخر لحظة. أيضًا أرسلوا إيميل تقدم فيه طلب تعويض سكن/سفر. - أرامكو السنة هذه أخذوا عدد كبير جدًا من الطلاب، قبولنا \\(السمر\\) جاء قبل الفاينلات بشوي، مع العلم أنه كان في رسائل قبول قبلها لكن الرسمية الرسمية كانت قبل الفاينلات. - المكافأة نزلت مرتين، المرة الأولى 3080 ريال و الثانية تقريبًا 1400 ريال. - نصيحة حاولوا تاخذون كل الملفات اللي تحتاجونها لكتابة الريبورت قبل ما تخلصون، و اللي يكتب الريبورت و هو هناك أفضل و أفضل. - هذا اللي عندي و إن شاء الله ما نسيت شي، اللي عنده أي استفسار يتفضل حاضرين 😆أتمنى الموضوع يكون مفيد للدفعات القادمة و شكر خاص للشباب اللي شاركوا بالاستبيان، في ميزان حسناتكم إن شاء الله![upload_2018-9-12_1-7-18.png|696x321](upload://tvtYZymrwuQrTPNhWDrmwvkBWV8.png)", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/180148/1", "user": "M_nd_m", "ts": 1536768136000, "tid": 180148, "pn": 1}}', 1536768136000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1392453-me399', 'stk-ibra1991', 'ME 399', 'info', '{"desc": "أتمنى أني اقدر أفيدك بتجربتي انا ميكانيكا سينس يعني بس عندي صيفي\nخلصت تدريبي بشركة الكهرباء الصيف هذا133\nالجامعة تعطي الطالب إختيارين اما انه يجيب فرصة التدريب (وهذا أفضل للجامعة) او الجامعة توفر له ( في يوم المهنة او عن طريق موقع التدريب\nهذا الشي سي للطلاب لان الشركة تنزل فرصتين وفيه عدد كبير من الطلاب )\nطبعا قبل سنتين من التدريب انا كنت ابحث عن الفرص بنفسي لآني اعرف تعقيدات الجامعة والإجراءات الي يطلبونها\nوكنت اروح للشركات واسأل عن فرص التدريب الصيفي عندهم و وش الإجراءات المطلوبة لكن فيه لخبطة كبيرة عند الشركات\nلان فيه برنامج اسمه هدف تابع لمؤسسة الموارد البشرية لجميع الطلاب حتى الي بالمدارس او حتى الي مو موظفين\nالحكومة تلزم الشركات انهم يدربون المتقدمين عن طريق البرنامج هذا.\nبالنسبة لشركة الكهرب انت تختار المنطقة وتروح للمحطة الي بالمنطقة الي تبغاها وتقدم عليهم لكن احيانا يكون عندهم ضغط لان الجامعات الي بنفس المدينة ترسل طلابها لازم تراسلهم من بدري\nانا لما رحت للكهرب طبعا لازم تكون عندك وثيقتين نموذج بيانات تعبيه الشركة (اسم المشرف عليك ارقام تلفونات الخ) والثاني خطاب من الجامعة انك مرشح للتدريب حتى الشركة تقبلك\nالوثيقتين للأسف الجامعة ما تصدرهم إلا بفصل واحد قبل التدريب وانت تكون مشغول بالدراسة وصعب علي انك تقدم\nراح اكتب رد ثاني اجاوب عن باقي الاسئلة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/164299/2", "user": "ibra1991", "ts": 1408798916000, "tid": 164299, "pn": 2}}', 1408798916000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1093469-me399', 'stk-metallic', 'ME 399', 'info', '{"desc": "^^\n\nسبق وطالبت بالمنتدى وإلى الآن والموضوع مسحوب عليه ، طبعاً أخذت وعطيت مع الماهر بس معد رد علي\n\nوهذا آخر رد له\n\nطبعاً رديت عليه رد طويل عريض بس ما بعد شافه … المشكلة أن لي حوالي شهرين وأنا كل يوم أروح أشيك عليه …\n\nوهذا اقتباس من الموضوع نفسه ، بحكم أنه في قسم الاقتراحات ولا تقدرون تشوفونه :\n\nالسلام عليكم …\n\nأرجو التكرم باضافة المواضيع التالية في قسم تقييم المواد الدراسية في قسم الهندسة الميكانيكية … حاولت اضافة المواضيع لكن هناك صلاحية لايمكن لمعرفي تجاوزها … وأيضاً حاولت التواصل مع المشرف “تقييم” لكن ما كان فيه وسيلة للاتصال فيه …\n\nالمواضيع هي :\n\nMe 351 applied mechanical engineering cooperative work\n\nme 399 summer training\n\nsenior design project\n\nشكراً لك … وأرجو الاستعجال بها …\n\nبودي لو يطرح كم عضو معي نفس هالموضوع بقسم الاقتراحات عشان يؤخذ بمحمل الجد، ولا يطنش مثل الموضوع اللي حطيته …\n\n🌹", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coop/131994/3", "user": "METALLIC", "ts": 1347724443000, "tid": 131994, "pn": 3}}', 1347724443000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p884270-me399', 'stk-user6853', 'ME 399', 'info', '{"desc": "مدى سهولة/صعوبة ايجاد شركة تقدم برنامج تدريب لغير الأمريكيين ؟\nاذا عن طريق الجامعة,كل ماكان معدلك اعلى فرصتك اكبر,طبعا على حسب المتنافسين يعني ممكن تكون اعلى واحد وانت معدلك 2.4…واذا عن طريق المراسلات سهل اذا بحثت من بدري…\nللمعلومة عن طريق الجامعة مافي الا صيف وترم اول\n\nما هي الشركات التي ينصح بها للمهندسين الميكانيكيين؟\nمدري\n\nتأثير محل التدريب على المتدرب بعد التخرج (وقت التقدم على الوظائف)؟\nبس تنفعك في السي في تهايط عليهم…وممكن الشركات الصغيرة يكون لك اولوية…لكن سابك,ارامكوا…ماتفرق\n\nعلى العموم اذا تيسرت انصحك وبقوة…اقل شيء تضمن لغة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/110671/3", "user": "user6853", "ts": 1313142533000, "tid": 110671, "pn": 3}}', 1313142533000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1161603-me399', 'stk-amat_24', 'ME 399', 'info', '{"desc": "اذا تحب تتعلم كيف تشتغل بعض الاجهزة من الناحية الميكانيكية :\n\nhttp://www.howstuffworks.com/\n\nالموقع جدا رااائع!\n\nلا تتوقع انك راح تدرس بعض تفاصيل عمل الاجهزة في الجامعة لانه دراسة الهندسة نظرية، على اساس انه بعد كذا الشركات تدربك على انظمتها اذا احتجت\n\nبالرغم من ذلك، اذا رحت مقابلات شخصية توقع انه الشركات راح تسالك بعض التفاصيل عن بعض الاجهزة قد تكون ما درستها في الجامعة… هذا الموقع انقذني في مقابلتين!\n\nسئلت مرة عن انواع محركات الطائرات ومرة عن انواع الـcompressors في المكيفات\nوالحمد لله كنت قاري عنها في هذا الموقع. لغته سهلة الفهم سواء للمهندس او لغير المهندس\nانصح اي واحد رايح مقابلة يقرى عن بزنس الشركة ويدخل هذا الموقع يراجع\n\nاذا عندك فضول عن شيء وحاب تعرف كيف يشتغل ، راح تلاقي هذا الموقع كنز من المعلومات!\n\n-----------------------------\n\nاذا عندك اهتمام في الـmanufacturing بشكل عام:\n\nHow It’s Made\n\nوثائقي رائع عن عمليات الصنع لاي منتج قد يخطر في بالك!!\n\nانا قضيت تدريبي الصيفي في مصنع زجاج، وجدت نفس العمليات مشروحة بالفديو في وحدة من الحلقات ومصورة داخل مصنع،، كانهم جو عندنا المصنع يصورو لاني شفت نفس الاجهزة بالظبط\n\nممكن تلاقي فيه تصوير لمصانع لاي شي من سيارات الى شفرات حلاقة\n\nعلى ما اذكر حملته من الـtracker، واحد من الشباب كان رافع كل الـseasons كاملة\n\nاذا ما حصلته تقدر تدور في اليوتيوب. هذا الرابط فيه مجموعة طيبة:\nhttp://videos.howstuffworks.com/science/how-its-made-videos-playlist.htm#video-40580\n\n---------------------------------\n\nاذا عندك اهتمام شديد بالـgeometric 3D modeling (على الـsolidworks) انصحك تتعلم عن الـsurface modeling\n\nطريقة قوية جدا في تشكيل القطع ما تعلمناها في ME210. قطع كثيرة مستحيل تتشكل بالطريقة المعتادة (Solids Modeling) دون اللجوء الى الـsurfacing\n\nهذا فديو تدريبي تقدر تستعمله كبداية:\n\nhttp://www.youtube.com/watch?v=fA2-i34UVUo\n\nهذا فديو ماهو تعليمي بس يبين لك قوة الـsurfacing\nhttp://www.youtube.com/watch?v=45yF6J3fpQI\n\nطبعا مستحيل تسوي body حق سيارة بالـsolids modeling\n\nفديو ثالث يبين لك ان ممكن تبني الـsurface من الـdraiwing بدل ما تسوي العكس وتبني الرسمة من المجسم الـ3D:\nhttp://www.youtube.com/watch?v=UKHWUH7UASI", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/138145/3", "user": "amat_24", "ts": 1357834378000, "tid": 138145, "pn": 3}}', 1357834378000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1404830-me399', 'stk-user3498', 'ME 399', 'info', '{"desc": "السلام عليكم\n\nتلقيت طلب من احد الاعضاء بأن اقوم بعرض تجربتي في الدراسة والوظيفة بعد التخرج كمهندس مدني , ولتعم الفائدة سأقوم بتقديم نصائح لكافة المراحل في التخصصات الهندسية , وبالنسبة للهندسة المدنية سأقوم بكتابة موضوع منفصل عن تجربتي الشخصية\nسأقوم بترتيب المقال على شكل نقاط مختصره لاختصار الوقت وتبسيط الفكرة\n\n, دعواتكم لي بالشفاء اعاني من مشكلة في الظهر\n\nأولا : الاوريا :\n\n- قد تكون اصعب مرحلة في الجامعة لعدة عوامل منها :\n\n1- التغير المفاجئ في نمط الحياة ( ساعات الدوام الطويلة )\n\n2- المناهج الجديدة ونمط الاختبارات والكويزات والهوموورك المختلف كليا عن الدراسة العادية\n\n- سوف تقوم بدراسة مواد متعدده غالبا لتحديد ميولك الابتدائي , مثلا اذا احببت الفيزياء : ميكانيكال , كيميا : كيميكال , رياضيات : الكتريكال وهكذا .\n\n- بعد السنة التحضيرية ستقوم بتحديد تخصصك الابتدائي\n\n- يجب عليك ان تبذل اقصى جهدك لان هذه اهم سنه ووجودك في الجامعة معتمد على هذه السنة ( لا تعتبر طالب في البترول الا بعد اجتيازها بنجاح ) , ابذل اقصى جهد واعتبر ان هذه السنة هي اهم سنة في حياتك كلها ، لان مستقبلك ( نوعيته وجودته ككل ) يعتمد على هذه السنة\n\nثانيا : التخصص :\n\n- اختيار تخصصك الابتدائي لا يعني شيئا في اول سنه ( فريشمان ) لأنك ستقوم بدراسة جميع المواد المشتركة مع باقي التخصصات الهندسية\n\n- بعد السنه الاولى ستقوم بدراسة بعض المواد التي ستعطيك فكره عن التخصصات , مثلا EE 204 ستعطيك فكره عن اليكتريكال , CE 201 ستعطيك فكره عن المدنية وهكذا\n\n- تحديد تخصصك المستقبلي يعتمد على السداسية التالية :\n\n1- ميولك الابتدائي من قبل الدراسة الجامعية\n\n2- ميولك بعد دراسة مادة من التخصص نفسه\n\n3- النتائج ( نتائج الاختبارات ، الكويزات ، الهوموورك ) : ارتفاع نتائجك في هذا المقياس يدل على ان التخصص هذا هو الانسب وذلك وفق معادلة : % الجهد + % الوقت ≈ 70-80% النتيجة\n\nمثال : لنفرض في مادة CE 201 وبعد استلام نتيجتك في الاختبار الاول : انت تعتقد انك بذت جهد كامل 100 % في التحضير للاختبار ( حل جميع الهوموورك + الكويزات + مذاكرة المقرر كامل ) ولم تقصر ابدا في بذل الوقت 100% فاذا كانت نتيجتك في الاختبار تساوي 70-80% او اعلى فذلك يعني ان التخصص الذي تتبعه المادة مناسب في الارجح لك ( هنا CE ) , اما اذا كانت نتيجتك دون ذلك فان التخصص لا يناسبك ابدا .\n\n4- حاجة سوق العمل :\n\nوهي ليست فقط عدد الوظائف , لتفهم حاجة سوق العمل يجب الانتباه للآتي : ( نسبة العرض الى الطلب + مستواك الاكاديمي مقارنة الى مستوى الطلاب في نفس التخصص )\n\nبمعنى : اذا فرضنا انك تفكر في دخول قسم الهندسة الكيميائية ، فعليك اولا ان تقيس حجم خريجي القسم في الفصل الواحد كمعدل ، مثلا 1000 طالب للفصلين الاول والثاني , وهذا العرض , اما الطلب فهو عدد الوظائف المتاحة في سوق العمل فمثلا بزيارة موقع يوم المهنة ، يمكنك معرفة عدد الوظائف المتاحة في ذلك الفصل مثلا 250 وظيفة ( بغض النظر حقيقية او لا ) .\n\nثم تقوم بقسمة العرض على الطلب لتكون عندك نسبة = 250/1000 = 0.25 بمعني ربع وضيفة لكل طالب وهذا سيء جدا ، كلما ارتفعت النتيجة عن 1 كلما كان افضل\n\nثم بعد اخذ فكرة عن العرض والطلب يجب عليك مقارنة هذا الامر مع مستواك الاكاديمي ، فمثلا اذا كنت تعتقد ان مستواك الاكاديمي يوازي C مقارنة بباقي الطلاب في التخصص , فذلك يعني ان نسبة العرض الى الطلب يجب ان تكون مرتفعة ( 2 او اعلى ) لان المنافسة ستكون شديده وستخسر موقعك في التقديم للشركات عند مقارنة المعدل\n\nاما اذا كنت تعتقد انك A ففي هذه الحالة لا يجب عليك القلق ان كانت نسبة العرض الى الطلب اقل من 2 او اقل من 1 ايضا .\n\n5- طبيعة العمل المستقبلي :\n\nيجب عليك الانتباه ان دخولك تخصص معين لا يعني بالضرورة ان ما ستقوم به في عملك هو تطبيق لتخصصك بالكامل ، بمعنى ان الدراسة شيء والعمل شيء اخر .\nيجب عليك قبل الاكمال في تخصصك ان تأخذ فكره واضحة عن الاتي : مجالات وطبيعة العمل في تخصصك ( مصانع –رقوق – مكتبي – الخ) + موقع العمل( موقع يوم المهنة ) + ساعات العمل ( 40 او اكثر في الاسبوع : بمعنى كم ساعة يوميا وكم يوم في الاسبوع ) + معدل الرواتب ( موقع يوم المهنة )\n\nوبعد اخذ فكرة يجب عليك ان تقوم بمقارنة هذا الامر بميولاتك الشخصية . وغالبا افضل طريقة لمعرفة هذا الشيء التدريب الصيفي او التعاوني ، ولكن التدريب غالبا يكون متأخر وغالبا الشركات غير جادة في تدريب الموظف , لذلك الافضل هو البحث الذاتي\n\n6- نظرتك الذاتية لمستقبلك :\n\nيجب ان تحدد هدف وظيفي واضح ، حتى لو لم يكن واقعي ،، فكما يقول المثل : صوب للقمر فان لم تصيب القمر ،، ستصيب النجوم\n\nمثال : انت ترى نفسك بعد خمس سنوات متزوج ولديك ابناء ،، اما وظيفيا فترى نفسك على المدى البعيد : موظف بمرتبة عالية ، مستقر وظيفيا ، مقتدر ماليا ؟ نوعية المرتبة وطبيعة عملها تختلف على حسب مجال العمل والتخصص وذلك تبعا لبحثك الذاتي … ففي هذه الحالة قارن اهدافك بتخصصك ومجالاته الوظيفية\n\nمثال2 : انت ترى نفسك تدير عمل حر بدون ساعات عمل محددة ولا رؤساء ،، تخصصك هو هندسه كيميائية ؟ غالبا في هذا التخصص مجال العمل الحر اصعب وأطول من المدنية مثلا . ( ابحث )\n\nمثال 3 : انت ترى نفسك معيد او باحث في الجامعة ؟ ابدأ بتكوين علاقات وتحسين نتائجك والبحث عن طريقة اكمالك ومتطلباتها .\n\nالخلاصة : بعد تحديد نتائجك في هذا السداسية ، ستقوم بتحديد التخصص المناسب لك او مدى ملائمة تخصصك الحالي\n\nفي الحلقة التالية سأقوم بعرض مرحلة ما بعد التخصص وبعض النصائح المفيدة .\nلأي طلب : s200678180@gmail.com", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/166127/1", "user": "user3498", "ts": 1413181464000, "tid": 166127, "pn": 1}}', 1413181464000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1369029-me399', 'stk-abdullatif1994', 'ME 399', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته …\n\nبما اني فاضي …\nعندي كم استفسار …\n1- انا بقدم على صيف 143 كـ سمر تريننق …\nوان شاء الله من خططتي اني بخلص 4 مواد لفل 3 مع Engl214… بس بينهم مادة 323 … الي هي لاب … فما ادري تحسب ولا لا … واذا ما تحسب هل احد جرب ياخذ بتشن مثل حالتي ؟\n2- من مته يبدأ تقديمي … هل من السمستر الأول ولا الثاني ؟ ولا بعد ما اسجل ME399 ?\n3- السي في لازم تكون شغل عدل 😦 ؟ …\n4- هل القبول يكون سهل ولا ؟ يعني أي شركه اقدم عليها تقبل .؟ ولا لازم مقابله بعد ؟\n\nوشكرا", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/summer-training/156194/35", "user": "Abdullatif1994", "ts": 1400756251000, "tid": 156194, "pn": 35}}', 1400756251000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1358078-me399', 'stk-_579', 'ME 399', 'info', '{"desc": "Your Request to Register Summer Training course: ME 399 is Not Approved by your Department Summer Training Coordinator on date:4/24/2014\nKindly add other courses through web and if you have any questions kindly contact your department Summer Training Coordinator\n\nوش السبب يااخوان تتوقعون\nهل لاني زلت الكورس في الصيف ولاني مارحت لهم ولا اخذت لا موافقه ولا اي شي\nيعني ماسويت اي شي للصيفي سوا اني نزلتها بالرجيستر غير كذا ماسويت شي\nمع العلم معدلي اقل من 2\nوهل لو رحت واخذت الموافقه بتمشي الامور ولا خلاص", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/160413/1", "user": "_579", "ts": 1398566606000, "tid": 160413, "pn": 1}}', 1398566606000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1488396-me399', 'stk-mosab_j', 'ME 399', 'info', '{"desc": "الشهادة معتمدة من معهد الجبيل التقني\n\nوهذي معلومات عن البرنامج\n\nرنامج الصيفي للمهارات الفنية الهندسية والتقنية للمهندسين و طلاب الجامعات السعودية\n\nتعريف البرنامج : هو برنامج محاكاة العمل الفني والهندسي لابرز المنشآت الصناعية و شركات توليد الطاقة وهو معتبر بمادة التدريب الصيفي بالجامعات السعودية وغيرها\n\nالهدف من البرنامج : برنامج تدريبي يركز على تنمية أبرز المهارات الفنية والتقنية للمهندسين والتي تطلبها طبيعة العمل في القطاع الصناعي\n\nالفئة المستهدفة : طلاب و المهندسين تخصصات الهندسة الميكانيكية والكهربائية و الصناعية و الهندسة الكيمائية - طلاب الكليات التقنية\n\nطريقة التدريب : التدريب بطريقة ادارة المشاريع عدد ساعات التدريب : 270 ساعة تدريبية يشملها شهادة معتمدة\n\n: مميزات البرنامج\n\nمحاكاة العمل الهندسي لابرز المنشآت الصناعية ومحطات توليد الطاقة الموجودة بالجبيل الصناعية #\n\n# ترسيخ المهارات الهندسية الفنية للمهندسين باعداد مشاريع تخرج خلال فترة التدريب\n\n# التدريب وفق معايير دولية خاصة بمصانع و محطات توليد الطاقة للمدن الصناعية\n\nشهادات معتمدة من معهد الجبيل التقني بالهيئة الملكية #\n\nزيارات لابرز الشركات و المنشآت الصناعية بمدينة الجبيل الصناعية #\n\nسكن لكل المتدربين خلال فترة التدريب #\n\nيعتمد البرنامج التدريبي على اللغة الانجليزية للمفردات التقنية والهندسية #\n\nمعرض للمشاريع المنفذة خلال فترة البرنامج ودعوة ابرز الشركات والمنشآت الصناعية بالجبيل الصناعية #\n\nبرامج ترفيهية وثقافية وواجهة بحرية خلابة #\n\nمدة البرنامج : شهرين لمدة 7 اسابيع تدريبية\n\nبداية البرنامج يوم الاثنين تاريخ 10/10/1439 الموافق 24/6/", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/178856/5", "user": "Mosab_j", "ts": 1519409403000, "tid": 178856, "pn": 5}}', 1519409403000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1508127-me399', 'stk-aloosh27', 'ME 399', 'info', '{"desc": "مقابلتي كانت اليوم مع قسم SAOO\nتخصصي هندسة ميكانيكية\nاثنين قابلوني في البداية عرفوا عن نفسهم وتكلموا لي عن القسم والمواقع اللي يغطونها وسألني وين حاب تشتغل في أي موقع؟\nبعدها قال لي الآن جا دورك\nTalk about yourself and your SDJ and Summer Training\nوسألني بعدها عن السينير ديزاين.\nسألني ان مستواك اول سنتين كان نازل وفجأه رفعته، وش كان السبب؟ وكيف رفعته؟\nانا كنت حاذف صيف وسألني ليش حذفته؟\nاسئلة التكنكال كانت:\nDraw stress strain curve\nDraw young modules of Elasticity\nWhat is cavitation and how to avoid it\nDraw the velocity distribution of external flow on plate\nDraw the velocity distribution of internal flow in pipes\nCan you list some static equipments\nWhat are the types of corrosion\nIf you have flow velocity in pipe how can you get the volumtric flow rate\nفي الاخير قال لي اكتب خلال دقيقة عن رؤية السعودية 2030 وبعد م خلصت قال اقرأ اللي كتبته\nوبكذا انتهت المقابلة وسلمت عليهم وطلعت\nالمقابلة كانت اخويه سوالف ودردشه 👍\n\nبالتوفيق جميعاََ", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/april-2019/181200/42", "user": "aloosh27", "ts": 1554127315000, "tid": 181200, "pn": 42}}', 1554127315000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1131241-me399', 'stk-a7madd', 'ME 399', 'info', '{"desc": "معك 100%…\n\nعطيته موظفهم السي في وقال لي بنسوي لك مقابلة شخصية ما عندك مشكلة؟ قلت له اكيد، قاللي خلاص بس تعال بعد ربع ساعة. كتب معلوماتي وقاللي عندنا زحمة، تعال بعد ساعة.\nجلست انتظر وأدور في المعرض بعدين جيتهم على الوقت، قال لي خلك حولنا دورك قريب قلت أوكي …\nشوي جاني الرجال وقاللي جاهز؟ قلت له ايه جاهز. نادى خويه وقال له يسويلي المقابلة، جا خويه سولفنا شوي وجلس يكتب معلوماتي وبعدين قال والله شوف، أنا أشوف أنك أحسن تقدم لنا السمستر الجاي عشان ما أظلمك، يمكن تضيع ورقتك ويمكن ننسى أو أي شيء، وش رايك؟ أنا أنقهرت وقلت له خلاص شكراً ومشيت.\n\nهي واحد من أثنين، يا أنهم يحكمون على الناس بالانطباع الأول أو بمظهرهم ويقررون إذا نبغى هذا الشخص أو لأ، أو أنهم فقط مستهترين وعديمي الاهتمام.\n\nوكل الحالتين يدلون على عدم كفاءة، وسوء تنظيم، ولا مبالاة، للأسف.\n\nملاحظة: تقديمي كان للتدريب الصيفي - هندسة ميكانيكية.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/135888/27", "user": "A7madd", "ts": 1354627512000, "tid": 135888, "pn": 27}}', 1354627512000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1011727-me399', 'stk-user2728', 'ME 399', 'info', '{"desc": "إعلان ارامكو (وباقي إعلانات التدريب الصيفي) يوصل عادة للي مستواهم جونير وسينير\nفما هي مقصودة أبدا لك أنت شخصيا\n\nإذا أنت بتتخرج في 131\nفيه صيف آخر 123 يمديك أيضا تأخذ فيه سمر تريننق وهو الأفضل\nلأنك تقريبا أنهيت كافة الكورسات إللي راح تفيدك في التطبيق وبتساعدك تفهم التطبيق بخلفية علمية ممتازة\n\nإذا أنت مخلص متطلبات التريننق وناوي الصيف تنزل 113\nأول شيء: التسجيل بأرامكو إنتهى وما لك إلا الواسطة أو تروح لهم مركز التوظيف تطلب منهم يسجلونك هناك\n\nثاني شيء: التسجيل بالشركات الثانية:\nإنتظر تقريبا لمدة شهر بتلقى إدارة التدريب موضحة لكم كل التفاصيل وعارضة لكم الشركات إللي بتطبقون فيها\n\nونصيحتي يفضل أنت تجيب الموافقة من الشركة ولا تعتمد على الجامعة، لأن تخصصات الكهرباء والميكانيكا والكيميكال فيه عروض قليلة لهم مقارنة بالطلاب إللي رايحين يطبقون خلال آخر سنتين", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/123220/2", "user": "user2728", "ts": 1332098138000, "tid": 123220, "pn": 2}}', 1332098138000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1454762-me399', 'stk-chelsea_17', 'ME 399', 'info', '{"desc": "أنا حاليا عندي تدريب صيفي بمشروع سكني لأرامكو وعمل مهندس الـPMT بس يجي يراقب الشغل ربع ساعه ويدور على كذا موقع ويرجع المكتب يكتب ريبورت (تخصصه ميكانيكال), في مهندس مدني فلبيني يعمل مع أرامكو هو اللي ماسك الإشراف ويتأكد أن البناء مطابق للمواصفات, وفيه مهندسين أرامكو من قسم الـ inspection يجون أحيانا قبل صب الخرسانة يتأكدون مثلا أن الحديد تم تركيبه وتوزيعه بطريقة سليمة وغيرها من الأمور الفنية لأن بعد الصب ما يمديك تتأكد من الجودة الا اذا كسرت الخرسانة.\n\nفباختصار في عملي الحالي شغل الـPMT اداري و coordination بين أرامكو والمقاولين وممكن يشتغل على مشروع مش من تخصصه أما قسم الـInspection لازم تكون فاهم بتخصصك.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/pmt/174281/4", "user": "Chelsea_17", "ts": 1470232030000, "tid": 174281, "pn": 4}}', 1470232030000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p276208-me399', 'stk-bossi', 'ME 399', 'info', '{"desc": "السلام عليكم\n\nشباب الي يعرف شركات تقبل التدريب الصيفي وتكون الشركات في الشرقيه…\n\nللمعلوميه قدمت على ثلاث شركات عن طريق الجامعه والى الان لا يوجد رد منهم…!!!!\n\nوان بحاجه الى معرفه شركات مهما كانت هذه الشركات تقبل التدريب الصيفي…\n\nالله يوفقكم اخوكم محتاج مساعد ارجوكم لا تبخلوا عليه محتاج الرد ضروري…\n\nطبعا انا طالب ميكانيكال\n\nالله لا يهينكم\nسلام", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/63868/1", "user": "bossi", "ts": 1214085934000, "tid": 63868, "pn": 1}}', 1214085934000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1443818-me399', 'stk-abu_khaled', 'ME 399', 'info', '{"desc": "المقابلة الاولى تكون مع شؤون الموظفين, تعرف بنفسك, وش تعرف عن الشركة وليش اخترتها, نقاط قوة ونقاط ضعف ومن الاسئلة هذي\nاهم شيء لا ترتبك وحاول تكون طبيعي جهز نفسك زين وجهز الـ cv , البس لبس محترم\n\nاذا عديت هذي المقابلة ان شاء الله , فيه اختبار تحريري, رياضيات , انجليزي , فيزياء (ميكانيكية و كهربائية)\n\nبعدين المقابلة الثانية, بيقولون لك تجهز برزنتيشن بتتكلم فيه عن نفسك, مشروع التخرج, التدريب الصيفي او الكو اب , وش تعرف عن الشركة و ليش اخترتها (اذا وصلت للمقابلة الثانية بيرسلون لك ايميل موضح فيه الي يبونه منك في البرزنتيشن و كم الوقت الي عندك) يوم مقابلتي قالو لنا كل واحد له 15 دقيقه, القينا البرزنتيشن قدام 5 من المدراء + مدير التوظيف و طبعا بعد البرزنتيشن بيسؤلونك, عاد الاسئلة هذي صعب تحددها, مثل واحد سألوه تعرف كم قيمة برميل النفط اليوم؟ !!!\n\nاذكر ذاك اليوم اكثر من واحد جاله نفس السؤال: عندك مشكلة لو تشتغل في جنوب افريقيا؟\n\nبالتوفيق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/172407/7", "user": "abu_khaled", "ts": 1457290576000, "tid": 172407, "pn": 7}}', 1457290576000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1512774-me399', 'stk-mhran515', 'ME 399', 'info', '{"desc": "انا اخوك من جامعة ام القرى تخصص هندسة ميكانيكية معدلي 3.50 من 4 … تخرجت بتاريخ 1440/5/9 هـ\nالتدريب الصيفي عندنا في ام القرى تدريبين كل واحد مدته شهرين\nالاول كان في مصنع كسوة الكعبة المشرفة في مكة\nالثاني كان في شركة الكهرباء محطة التوليد في مكة\n\nوالله ما لقيت اي وظيفة وانا اقلك يا غالي اذا تسوي في خير وتلقى اي شي لي حتى لو بمنطقة خارج الغربية ماعندي اي مشكلة اروح والله لاني والله بحثت واجتهدت في البحث عن وظيفة “مهندس ميكانيكي” وما لقيت…\n\nبالنسبة لكلامك عن ارامكو فعلا انت صادق ارامكو حلم كل واحد يتمناه لكن يوم تقارنهم مع المعلمين غلط لان احنا المهندسين قليل جداً الي يلقى فرصة بارامكو او شركة مثل مميزاتها اما المعلمين حتى الهامل ابو معدل 1.5 يصبر كم سنة وينزل تعيينه\n\nوزي ما قلت انت انا شفت الوضع وفكرت مالقيت بهالوقت شي افضل من العسكرية وقلت لاصحابي اللي مايبونها وما قدموا عليها قلت لهم بالحرف الواحد انا احترم رايكم لكن اقعدو صدقوني محد يوظفكم والسنة الجاية بشوفكم جايين تقدمون على العسكرية لكن ان شاءالله فال الله ولا فالي\n\nوالجندي يا اخوي يستلم مع البدلات 7 الاف ونص وهو بعد الثانوية اخذ دورة مدتها 4 شهور وفيه قطاعات زي الحرس الملكي الجندي اللي داخل بالثانوي يستلم 8 الاف ونص غير الشرهات اللي تجيه بين فترة وفترة\n\nلكن العسكرية ماهي مثل ارامكو … ارامكو او الشركات بشكل عام كل شي تسويه بحق مافيه شي تسويه بلاش صح انها كرف لكن كل شي له بدل اوفر تايم الخ … ما يضيعون تعبك\nاما العسكرية ترابط وتستلم وتجلس وقت واحيانا تنحرم من الاعياد واجازات السنة اللي كل الناس يوجزون فيها ومالك لا بدل ولا اوفر تايم ولا شي انما يعتبر هذا من واجبك\n\nعموما الدنيا حظوظ والله انا افكر الان اقول ليتني دخلت اي حاجة ثانية… رياضيات او لغة عربية او شريعة\nكان مديني لقيت اشياء كثيرة\nحتى لو كنت افكر بالعسكرية ما كان تعبت نفسي بالهندسة كان اخذت لغة عربية ودخلتها\nلكن الله المستعان والله شي يحزن", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/181748/26", "user": "mhran515", "ts": 1563789937000, "tid": 181748, "pn": 26}}', 1563789937000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1438203-me399', 'stk-fao95', 'ME 399', 'info', '{"desc": "السلام عليكم\n\nاحتاج مشورتكم ي شباب … انا طالب هندسة ميكانيكيه معدلي ظ¢.ظ¢ من ظ¤ … جدا سئ > والمخجل في الموضوع اني مو من جامعتكم ، من جامعة ام القرى وللاسف جامعتنا الموقرة تتعامل مع شركات متواضعه جدا جدا في التدريب الصيفي (وكالة عبداللطيف جميل ، شركات محليه بسيطه … الخ) ، وسبب كتابتي للموضوع هذا هو ثقتي الكامله فيكم ي طلاب جامعة الملك فهد … انتم غير عن طلاب الجامعلات الثانيه + في امور التدريب تحتكون في شركات طيبه ولكم خبره في المواضيع هذي .\nوانا بصراحه افكر اجيب ورقه من شركات محترمه في الشرقيه مثل ويثيرفورد شلمبرجير سابك … الخ واقدمها للقسم واخلص الهرجه …\n\nبس اللي مصعب الموضوع علي ثلاث شغلات:\n\nظ،- هل شركات كبيرة بالحجم هذا تدرب طالب بمعدلي من جامعه متواضعه ؟\nظ¢- فرضا تدرب … كيف اتواصل معاهم ؟ مع العلم اني خشيت موقعهم ولا حصلت اي شي بخصوص التدريب … مجرد التقديم ع وظيفه اذا كنت خريج بكلوريس …\nظ£- فرضا ما توفقت في قبولهم لي … ايش تنصحوني بشركات وكيف اتدرب عندهم ؟", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/171493/1", "user": "fao95", "ts": 1452125484000, "tid": 171493, "pn": 1}}', 1452125484000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1347245-me399', 'stk-user5272', 'ME 399', 'info', '{"desc": "تدريب صيفي في أرامكو عام 2011 ميكانيكا\n\nأول يوم أعطوني يوزر للجهاز ، وتعرفت على الموظفين وداومت نص يوم\n\nثاني يوم رحت للسوبرفايزر وطلبت منه خطة تدريب 8 أسابيع لأن الجامعة تطلب هالشيء من الطلاب\nوخلصت باقي الاوراق المطلوبة\n\nمن بعدها ، السلام عليكم عليكم السلام فقط\nماحد معطيني وجه\n\nبسبب الملل ، كنت أدور للشغل واجلس مع كل موظف وأسأله عن الشغل وكذا وأطلع للميدان أحيانا\nبكذا كنت على الأقل أشغل نفسي بحاجة مفيدة لي وللريبورت بعدين\n\nالشغل في السمر تريننق يعتمد على الشركة وعلى الادارة والمدير\n\nحاول تدور لنفسك شغل ، تاخذ أوراق مشاريع قديمة وتقراها ، تاخذ صور للمشاريع الحالية لو كان مسموح ، تفهم آلية العمل\n\nبالنسبة للدوام ، يكون كأنك موظف عادي لين تخلص الـ 8 أسابيع\n\nالصيف الجاي ما يمدي تخلص 8 أسابيع قبل العيد ، لازم ترجع وتخلص اسبوعين أظن\n\nكلم المدير لو كان يمديك تداوم لين العيد وماعاد ترجع بعده", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/159195/8", "user": "user5272", "ts": 1396428113000, "tid": 159195, "pn": 8}}', 1396428113000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p758962-me399', 'stk-user5266', 'ME 399', 'info', '{"desc": "هلا يالذيب 🙂\n\nاسمع يالغالي …رح للديبارتمنت … وتلقى عندهم كلكريوم ورقه أم وجهين الوجه الاول في الخطه الدراسيه والوجه الثاني فيه الخطه الشجريه 🙂\n\nبس على ما أذكر إن المواد المطلوبه هي :\nME315\nME309\nME316\nEngl214\nويمكن ME307 منب متأكد\nطبعا هالمواد لهم مواد تفتحهم وأهمها ME311 🙂\n\nوالله يوفقنا وياك 🙂", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/summer-training-pre-requisites/100352/4", "user": "user5266", "ts": 1294353697000, "tid": 100352, "pn": 4}}', 1294353697000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1447153-me399', 'stk-hamd00ni', 'ME 399', 'info', '{"desc": "السلام عليكم\n\nاخوكم طالب ميكانيكال في الجامعة هنا…\n\nتدريبي الصيفي ان شاء الله في الصيف القادم 153\n\nبحمد الله وتوفيقة توفرت لي فرصتين تدريب\n\nالاولى في شلمبرجير والثانية في أرامكو\n\nلازم أختار وحده منهم بسرعة\n\nمع العلم ان فرصة ارامكو رح تكون بمشيئة الله في مدينة المبرز بالأحساء (اللي عنده معلومات لا يبخل علي الله يجزاه خير)\n\nللأمانه أنا أبغى أتوظف في أرامكو بعد التخرج\n\nلكن ودي أجرب بيئة العمل في شملبرجير\n\nطبعا معدلي عادي ماني اونر ولا حاجة عشان كذا ما أضمن وظيفة في ارامكو بعد التخرج\n\nمن واقع خبرتكم…هل فرصة التدريب الصيفي لو أخذتها في أرامكو بتساعدني بشيء ولو بسيط اني أتوظف في أرامكو بعد التخرج؟؟؟\n\nطبعا لو كان الجواب لا… رح اتوكل على الله وآخذ تدريبي في شلمبرجير، بس اذا ايه التدريب له تأثير على الوظيفة رح آخذه في ارامكو اكيد ان شاء الله\n\nياليت تعطوني نصايحكم بخصوص التدريب في كل الشركتين وخصوصا أرمكو…هل فيه شيء أقدر أسويه أثناء التدريب عشان أجذبهم يوظفوني بعد التخرج؟\n\nشكرا لكم وجزاكم الله خير", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/173037/1", "user": "Hamd00ni", "ts": 1461180342000, "tid": 173037, "pn": 1}}', 1461180342000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1377291-me399', 'stk-nigma', 'ME 399', 'info', '{"desc": "إعلان عن توفر فرص تدريب\n\nتعلن شركة ) Fablab Dharan) عن توفر فرص تدريبية التالية في برنامج التدريب الصيفي وبالتنسيق مع إدارة التدريب في عمادة شؤون الطلاب :\n\n· هندسة ميكانيكة\n· هندسة الحاسب الآلي\n· العمارة\n\nعلى الراغبين في التقدم على هذه الفرص، ارسال السيرة الذاتية على البريد الالكتروني :\n\nb.alsaif@fabladhahran.org\n\nالأستاذ / بدر أكرم السيف\n\nجوال / 0503815230\n\nإدارة التدريب\n\nالتدريييييييب في الجامعة", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/161274/21", "user": "Nigma", "ts": 1401923484000, "tid": 161274, "pn": 21}}', 1401923484000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1456877-me399', 'stk-user8581', 'ME 399', 'info', '{"desc": "2 - إجرائات الجامعة / الشركة .\nطريقة التقديم : في نهاية الأسبوع العاشر من السمستر الثاني القسم يرسل للطلاب المرشحين للتدريب رسالة عن فرص تدريب بشركة JGC فيها شروط القبول في التدريب الخارجي بالإضافة لشروط الشركة .\nالشروط غالبا :\n- سعودي الجنسية ( شرط الشركة )\n- معدل 3 ( وأحيانا 2.75 )\n- ما سبق للطالب إنه طلع في برنامج التبادل الطلابي أو زيارات دولية\n- افرج قريداته في الانجلش C+\n\nوهذه هي رسالة من قسم الهندسة المدنية :\n\n[/quote]\n\n[quote]\n\nTo Summer Training Students in Term 153 :\nI want to inform you that as part of the cooperation between JGC Company (Japan) and Saudi Arabia , there is ONE opportunity for a civil Engineering student to train in Japan. The requirement to be a candidate include : CGPA & MGPA 2.75 or above , average English courses grade C+ or better, and to be a Saudi national\nIf you plan to register for CE 399 in term 153 , and are interested and satisfy the minimum requirements please contact Dr Khathlan (16-138) as soon as possible and bring with you the following;\nCGPA =\nMGPA=\nGrades in ENGL 101 , 102 & 214 =\n\nبعد اسبوع القسم يرفع أسماء الطلاب المرشحين لإدارة التدريب و عمادة شؤون الطلاب . وبعدها راح يطلب منكم سكرتير إدارة التدريب نسخة من الـ cv والجواز والأحوال عشان يرسلها للشركة … بعد أسبوعين راح تتواصل معكم الشركة ويسون معاكم مقابلة في مقر الشركة بالخبر . ( مكان الشركة )\n\nالمقابلة : تكون على حسب تخصصك وعدد الطلاب المرشحين معك : تقريبا المرشحين كانوا 6 طلاب\n3 طلاب من الهندسة المدنية : سو لهم إختبار يتكون من 3 أقسام لها علاقة بالأساسيات في CE201/CE203/ وعن structural steel لو جبت درجة سيئة في قسم structural steel علم الموظف إنك ماخذت الكورس . بعد الإختبار فيه مقابلة بسيطة والاسئلة فيها كلها شخصية مثلا قد سافرت لليابان أو برا السعودية ؟ , أهلك راضين إنك تدرب برا ؟ وش تعرف عن اليابان ؟ والهدف منها يعرف إنك مستعد وعادي عنك تطلع تدريب برا أو لا . ( طالب بس الي انقبل من الـ 3 )\n\nطالب من الهندسة الميكانيكة : المقابلة كانت شخصية وما سو له إختبار . ( مقبول )\nطالب من الهندسة الكهربائية : المقابلة كانت شخصية وماسو له اختبار . (مقبول )\nطالب من هندسة نظم التحكم والقياس ( انا 🤠 ) : المقابلة كانت شخصية وعن بعض أساسيات التخصص بدون اختبار . ( مقبول)\n\nنصيحتي في المقابلة حاول تبين له إنه عندك فكرة عن برنامج التدريب عندهم و أقسام الشركة وأنك مرن من ناحية التدريب برا السعودية وعندك فكرة عن الحياة في اليابان . اطلع على هذا الملف فيه نبذة عن الشركة وبرامج التدريب (link )\nنتائج المقابلة تعتمد على موعد المقابلة أنا علمني إني مقبول بعد المقابلة على طول أما الشباب الي من الهندسة المدنية بعد أسبوعين ردوا عليهم .\n\nبعد النتائج راح تبدأ اجرائات الشركة وفي نفس الوقت اجرائات الجامعة لكن عشان تكون الصورة واضحة راح اذكر اجرائات الشركة اول شي :\n\nاجرائات الشركة : ( الشركة متعاونة جداً والاجرائات سهلة جداً لكن السلبية الوحيدة هي لأن الاجرائات كانت على نهاية 152 فيمكن تضطر تراجعهم في الاجازة بين 152 و153 . )\n\n- بعد القبول بفترة راح يجتمع معكم موظف HR عشان يعطيكم فكرة عن البرنامج ويعطيكم خطة التدريب و تجيبوا معاكم : الجواز & الترانسكربيت & صور بقياس معين والصور بدون غطاء رأس .\n- الفحص الطبي كان مطلوب العام الماضي لكن هذي السنة ما كان مطلوب وعلى العموم لو كان مطلوب راح يعطيكم اوراق الفحص الطبي عشان تسونه في الجامعة.\n- قبل اسبوعين من موعد الرحلة راح يسلمكم الـ certificate of eligibility ماراح تقدر تدخل اليابان بدونها .\n- قبل أسبوع من التدريب راح يجتمع معاكم ويعطيكم اوراق عشان الفيزا وقبل اسبوع من موعد الرحلة راح يسلمكم الفيزا .\n- يوم الرحلة في الصباح راح يجتمع معكم ويعطيكم بعض الأوراق تحتاجونها اذا وصلتوا اليابان مثل عنوان السكن ( عشان تعبي الفورم الي يطلبه منك مكتب الهجرة او شرطة المطار …) و رقم الموظف المسؤول عنكم في اليابان .\n- راح يحددون لكم رحلةمعينة تحجزونها وغالبا تكون من البحرين الى اليابان وعلى طيران الاتحاد (طريقة الحجز في القسم الجاي)", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/174559/3", "user": "user8581", "ts": 1473112694000, "tid": 174559, "pn": 3}}', 1473112694000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1497334-me399', 'stk-mohammedson', 'ME 399', 'info', '{"desc": "نوع التدريب ( Summer Training )\n\nاسم الشركة أو جهة التدريب :Petrorabigh\n\nالسنة : 2018\n\nالتخصص + الجامعة: KFUPM + ME\n\nمكان التدريب + القسم : Rabigh + Field Maintenance II Department\n\nالمكافأة : 2000 أو 3000 ريال شهريا انت وحظك ومافي سكن ولا بدل سكن. وقالوا لي المكافأة بتجيك نهاية التدريب لكن أثناء التدريب في اول شهر نزلوها.\n\nطريقة التقديم: Email\n\nإضافات : الفترة اللي اتدربت فيها كان عندهم في الشركة مشروع جديد اللي هو (phase II) فنحن في قسم ال field maintenance كان عندنا شغل كثير وحقيقة استفدت من ناحية اني اتعرفت وشفت الأجهزة الميكانيكية (مثل المفاعلات والمبادلات الحرارية والمضخات و الكمبروسرات … الخ) وهي تنفك وتتصلح. لكن للأسف ماكان في اي مهام يعطوني اياها انفذها وفي أحيان كثيرة كنت أجلس في المكتب كذا بدون شغل.\nالموظفين في قسمنا بشكل عام متعاونين ويحاولوا يفيدوك باكبر شكل ممكن. على كلام الشباب انه الموظفين في الأقسام الثانية أقل تعاونًا.\n\nيسمح لك كمتدرب بالاستفادة من مرافق سكن الشركة كالشاطئ والنادي الرياضي. وحقيقة انه الشاطئ جميل جدا ونظيف وكذلك النادي فيه جميع المرافق اللازمة.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/170460/74", "user": "mohammedson", "ts": 1533718587000, "tid": 170460, "pn": 74}}', 1533718587000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1054468-me399', 'stk-dr_engineer', 'ME 399', 'info', '{"desc": "السلام عليكم ورحة الله وبركاتة\n\nانا طالب هندسة ميكانيكية وعندي سمر ترينينق الحين. حبيت اسأل وشلون اعرف الديد لاين للبروقرس ريبوت. وش اكتب فيها. حاولت التواصل مع ادفايزري ومع ادارة التدريب لكن محد يرد. والويب سيتي للحين مافتح ولا اتوقع يفتح لأن ادفايزري مو حق تقنية ولا يحب استعمال الكمبيوتر .\n\nارجو الافادة منكم ولكم جزيل الشكر", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/summer-training-report/127385/1", "user": "Dr_Engineer", "ts": 1339484197000, "tid": 127385, "pn": 1}}', 1339484197000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1419335-me399', 'stk-khalid-f10', 'ME 399', 'info', '{"desc": "وعليكم السلام\nحياك الله اخوي\n\nاخوي انا سويت التدريب الصيفي حقي هناك في البروسس الانجيرينق\n\nبالنسبة للشركة بشكل عام تعتبر من أفضل الشركات وجو الشركة حبي بين الموظفين\n\nانا تخصص كيميكال فاشتغلت في هذا القسم بحكم اغلب الكيميكال ييشغلون هناك\n\nبحكم انك ميكانيكال اتوقع بتصير inspection engineer\nقابلت كثير ميكانيكال بهذا المسمى الوظيفي\n\nاو ممكن تكون maintenance engineer\n\nتحت هو المخطط التنظيمي للشركة\n\nموفق", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/168183/2", "user": "khalid-f10", "ts": 1418165895000, "tid": 168183, "pn": 2}}', 1418165895000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1437362-me399', 'stk-user10015', 'ME 399', 'info', '{"desc": "السلام عليكم\n\nتخصصي ME وخلصت ليفل 2 باقي مانزلت اي مادة me من ليفل 3 وسمعت انه من شروط التدريب الصيفي او التعاوني اتمام ليفل 3\n\nممكن انزل ثلاث مواد me ليفل 3 الفصل 152 فهل اقدر اتدرب بصيف 153\n\nاللي عنده ايميل المسؤول عن التدريب للME يفيدنا\n\nشكرا لكم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/me/171396/1", "user": "user10015", "ts": 1451414064000, "tid": 171396, "pn": 1}}', 1451414064000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1324704-me399', 'stk-user2352', 'ME 399', 'info', '{"desc": "السلام عليكم\n\nكما يعلم الجميع يعتبر التدريب الصيفي من متطلبات التخرج من الجامعة ومن أهم متطلبات تسجيله إنهاء مواد التخصص LEVEL3\nعلى الأقل اربع كورسات مع ENGL214،\nوقد كثرت الإستفسارات عن ذلك فحبيت أوضح الخطوات مختصرة في هذا الموضوع ،\nأولاً: خطوات تسجيل التدريب الصيفي :-\n\n1- تروح لمكتب ادارة التدريب وتأخذ ورقة التعريف والترشيح للتدريب والمكتوب عليها “to whom may it concern”\nومعها نموذج فرصة تدريب صيفي\n\n2- تبدأ عملية البحث عن فرصة تدريب في إحدى الشركات التي ترغبها أما بنفسك أو تنتظر ليوم المهنة ،إذا قبلوك يرسلون لك خطاب وتوديه لشؤون التدريب …وإذا لا سمح الله ماحصلت لك شركة , عمادة التدريب يوفرون لك فرصة في اي مكان والمميزات يمكن ماتكون نفس اللي ببالك . ولا تنسى اعداد سيرتك الذاتية CV التي بموجبها مع ورقة الترشيح راح تحصل فرصة تدريبية.\n\n3- في التسجيل المبكر للصيفي تضيف مادة التدريب الصيفي XXX399\n\n4- توقع أوراقك من الدكتور المنسق للتدريب في قسمك الأكاديمي COORDINATOR مثل الدكتور سميرالغضبان لقسم الهندسة الكهربائية والدكتور سيف الكعبي لقسم الهندسة الميكانيكية والدكتور سمير العامر لقسم هندسة النظم.\n\n5-بعد توقيع أوراقك توديها لإدارة التدريب من أجل اعتماد تسجيلك واصدار خطاب الموافقة واوراق التقييم\n6- بعد نهاية الفاينلات تروح ادارة التدريب وتأخذ أوراقك في ظرف مختوم توديه معك للشركة علشان تبدأ التدريب وترسل صورة بالفاكس لإدارة التدريب باسم المشرف عليك في الشركة\n7- مطلوب منك تسليم تقريرين مرحليين PROGRESS REPORTS الاول بعد الاسبوع الثالث والثاني بعد السادس\n\n8- بعد انتهاء فترة التدريب شهرين تبدأ تكتب FINAL REPORT وتسلمه للكوردينيتور وتستعد للبرزنتيشن والقريد في النهاية راح يتحول من IC إلى NP اجتياز\n\nلمعرفة آخر الفرص الوظيفية والتدريبية ،،\nارعص على الرابط\nhttp://cday.kfupm.edu.sa/opps_search.aspx\n\nنماذج مفيدة للـCV\nhttps://www.dropbox.com/s/jas5chtol345lai/CVs%20samples.rar", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/summer-training/156194/1", "user": "user2352", "ts": 1391126871000, "tid": 156194, "pn": 1}}', 1391126871000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1450910-me399', 'stk-fahad_2012', 'ME 399', 'info', '{"desc": "إعلان عن توفر فرص تدريب صيفي\n\nتعلن شركة (ABB ) ومقرها الرياض عن توفر فرص تدريبية في برنامج التدريب الصيفي وبالتنسيق مع إدارة التدريب في عمادة شؤون الطلاب :\n\n· الهندسة الميكانيكية\n· الهندسة الصناعية والنظم\n\no مميزات التدريب: راتب شهري ( 3500 ريال)\n\nعلى الراغبين في التقدم على هذه الفرص التدريبية إرسال سيرهم الذاتية للدكتور / محمود قصاص من خلال البريد الالكتروني التالي:\n\nmkassas@kfupm.edu.sa\n\nإدارة التدريب\nعمادة شؤون الطلاب\nجامعة الملك فهد للبترول والمعادن", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/161-152-153/170272/210", "user": "Fahad_2012", "ts": 1464782170000, "tid": 170272, "pn": 210}}', 1464782170000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p304213-me399', 'stk-user3467', 'ME 399', 'info', '{"desc": "ما ابي اعترض على كلامكم لانني طبقت 063 في ارامكو\nصحيح ان محد فاضي يشرح\nلكن افرض شخصيتك عليهم واكسب ودهم بالكلام والمعاملة عقبها بيفيدوك\nيحبيبي اول اسبوعين كرهت شي اسمه training\nلكن فكرت اني ادخل معهم بالغصب في اجتماعاتهم\nبعضهم يحسبني مندوب من شركة وذا اللي ساعدني خخخخخخ\nالسوبر فايزر كان روعة يوم شافني كذا مهتم\nصرت اروح للمعمل واشوف المعدات والمكاين وكيف تتم عملية البناء\nالصبح e-learning وبعد الغداء للمعمل\nحتى انه حدد كل يومين مع قسم اشتغل\nاما الربورت كان بصراحة روعة مليان صور للمكاين لاني ME\nنصيحة: قلل من الشرح عن ارامكو او الشركة وحاول تشرح عن الواقع (بايجابية) وحاول تهتم بالكتابة عن مجال تخصصك", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/summer-training/64446/14", "user": "user3467", "ts": 1219737242000, "tid": 64446, "pn": 14}}', 1219737242000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p685459-me399', 'stk-mku2111', 'ME 399', 'info', '{"desc": "الحين لما ارجع للجامعه … ايش اسوي علشان انهي اجراءات السمر ترينينق … اروح لادارة التدريب ولا اسلم الريبورت … ولا كيف …ارجو الايضاح …\n\nلما ترجع تتواصل مع قسمك وبالتحديد ( ادفايزرك في التدريب ) ممكن يكون هو نفسه ادفايزرك الاكاديمي على حسب توزيع كوردنيتور التدريب في قسمك ، تسلمه الفاينل ريبورت وهو يتكفل بالباقي\n\nثانيا … لمن اسلم الريبورت ؟…هل اسلمه للدكتور اللي اسمه مسجل عندي بالجدول … او مكان ثاني.؟!!\n\nشوف فيه أقسام تقول كل طلاب التدريب سلموا لها الدكتور زي قسم الميكانيكية اول كان الكعبي ومافيه ادفايزرز ولا شي بس سلم للكعبي وتوكل ، الحين صار الفرائضي ، وفيه اقسام توزع الطلاب على عدة دكاترة والمسؤول عن توزيع هو كوردنيتور التدريب اللي اسمه موجود في الريجسترار\n\nثالثا … انا ماسويت خطة تدريب … هل هذا فيه تأثير …؟؟؟\n\nمافهمت وش تقصد بالخطه التدريبية ؟", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/93607/3", "user": "MKU2111", "ts": 1282115733000, "tid": 93607, "pn": 3}}', 1282115733000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1468633-me399', 'stk-_me1', 'ME 399', 'info', '{"desc": "السلام عليكم\n\nطبعا شباب مثل ماهو واضح من العنوان انا طالب ميكانيكال مدسمس هذا السمستر بمعدل عام فوق 1.95\n\nالمهم السمستر 171 إن شاء الله باكون مخلص المواد المطلبوبة ليي للتخرج و بالنسبة للتدريب صيفي ما ادري كيف باخده خصوصا اني بتاخر يمكن سنة زيادة بس بسبب اني لازم اخلي سمستر بعده ! يعني بسبب انه مافي مواد ايلكتيف فالصيف واحتمال اخد التدريب في 172 ب petition وعلى هذا باتخرج 181 اذا مايقبلو الصيف 173 كسمستر بعد التدريب\nمن خلال خبرتكم\nهل راح يسمحو ليي ادارة القبول اخد التدريب هالصيف او سمستر 171 لو اعيد قبولي ؟\nهل في شركات تقبل طلاب بمعدل تحت 2 للتدريب ؟\nهل في شركات تقبل طلاب مااخدو التدريب يشتغلو على اقل كاتيكنشن حتى اشتغل فيها فترة الايقاف؟\n\nجزاكم الله خير", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/2-20/176110/1", "user": "_ME1", "ts": 1487510240000, "tid": 176110, "pn": 1}}', 1487510240000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1529959-me399', 'stk-saul', 'ME 399', 'info', '{"desc": "السلام عليكم ورحمة الله وبركاته،\n\nانا ادرس هندسة ميكانيكية ومفروض اطبق خلال الصيف لكن المشكلة قدمت على اكثر من ١٥ شركة وولا شركة ردت علي غير ارامكوا بالرفض (والحمدلله على كل حال) علمن انه معدلي عالي. باقي اقل من اسبوعين على بدء التدريب حبيت اشوف رأيكم واذا فيه احد عنده نفس المشكلة هذي من مختلف الجامعات في السعودية. الي اعرفهم من جامعتي نفس وضعي على حد علمي.", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/183893/1", "user": "Saul", "ts": 1621105397000, "tid": 183893, "pn": 1}}', 1621105397000, 1794826872, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
